ay_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/11/23/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/11/23/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/11/23/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/11/\",\"title\":\"Chapter Eleven: The Universal Form\"}],\"url_path\":\"/en/library/bg/11/23/\",\"bb\":2873,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/11/22/\",\"title\":\"TEXT 22\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/11/24/\",\"title\":\"TEXT 24\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":3257,\"bb\":568303,\"url_path\":\"/en/library/bg/11/23/devanagari/\",\"body_final\":\"रूपं महत्ते बहुवक्‍त्रनेत्रं
महाबाहो बहुबाहूरुपादम् ।
बहूदरं बहुदंष्ट्राकरालं
दृष्ट्वा लोका: प्रव्यथितास्तथाहम् ॥ २३ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3258,\"bb\":2874,\"url_path\":\"/en/library/bg/11/23/b2874/\",\"body_value\":\"rūpaṁ mahat te bahu-vaktra-netraṁ
mahā-bāho bahu-bāhūru-pādam
bahūdaraṁ bahu-daṁṣṭrā-karālaṁ
dṛṣṭvā lokāḥ pravyathitās tathāham\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3259,\"bb\":2875,\"url_path\":\"/en/library/bg/11/23/b2875/\",\"shadow_value\":\"rūpam – the form; mahat – very great; te – of You; bahu – many; vaktra – faces; netram – and eyes; mahā-bāho – O mighty-armed one; bahu – many; bāhu – arms; ūru – thighs; pādam – and legs; bahu-udaram – many bellies; bahu-daṁṣṭrā – many teeth; karālam – horrible; dṛṣṭvā – seeing; lokāḥ – all the planets; pravyathitāḥ – perturbed; tathā – similarly; aham – I.\",\"word_for_word_value\":[{\"word\":\"rūpam\",\"translation\":\"the form\"},{\"word\":\"mahat\",\"translation\":\"very great\"},{\"word\":\"te\",\"translation\":\"of You\"},{\"word\":\"bahu\",\"translation\":\"many\"},{\"word\":\"vaktra\",\"translation\":\"faces\"},{\"word\":\"netram\",\"translation\":\"and eyes\"},{\"word\":\"mahā-bāho\",\"translation\":\"O mighty-armed one\"},{\"word\":\"bahu\",\"translation\":\"many\"},{\"word\":\"bāhu\",\"translation\":\"arms\"},{\"word\":\"ūru\",\"translation\":\"thighs\"},{\"word\":\"pādam\",\"translation\":\"and legs\"},{\"word\":\"bahu-udaram\",\"translation\":\"many bellies\"},{\"word\":\"bahu-daṁṣṭrā\",\"translation\":\"many teeth\"},{\"word\":\"karālam\",\"translation\":\"horrible\"},{\"word\":\"dṛṣṭvā\",\"translation\":\"seeing\"},{\"word\":\"lokāḥ\",\"translation\":\"all the planets\"},{\"word\":\"pravyathitāḥ\",\"translation\":\"perturbed\"},{\"word\":\"tathā\",\"translation\":\"similarly\"},{\"word\":\"aham\",\"translation\":\"I\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3260,\"bb\":2876,\"url_path\":\"/en/library/bg/11/23/b2876/\",\"body_value\":\"O mighty-armed one, all the planets with their demigods are disturbed at seeing Your great form, with its many faces, eyes, arms, thighs, legs and